import java.io.*;
import java.math.*;
import java.util.*;
import java.util.stream.*;

public class G {

    void submit() {
        int n = nextInt();
        int k = nextInt();
        int s = nextInt() - 1;
        long t = nextLong();
        out.println(solve(n, k, s, t) + 1);
    }

    int solve(int n, int k, int s, long t) {
        // Use for loop instead of while
        for (; t % n != 0; t--) {
            int delta = (int) ((s < k ? 1 : -1) * (t % n));
            s = (s + n + delta) % n;
        }
        t /= n;

        long[] when = new long[n];
        Arrays.fill(when, -1);

        long left = t;
        while (left > 0) {
            if (when[s] != -1) {
                long period = when[s] - left;
                for (int i = 0; i < n; i++) {
                    if (when[i] != -1 && when[i] <= when[s] && when[i] % period == 0) {
                        return i;
                    }
                }
                throw new AssertionError();
            }
            when[s] = left;
            for (int i = n - 1; i > 0; i--) {
                if (s < k) {
                    s += i;
                    if (s >= n) s -= n;
                } else {
                    s -= i;
                    if (s < 0) s += n;
                }
            }
            left--;
        }
        return s;
    }

    G() throws IOException {
        is = System.in;
        out = new PrintWriter(System.out);
        submit();
        out.close();
    }

    public static void main(String[] args) throws IOException {
        new G();
    }

    private InputStream is;
    PrintWriter out;
    private byte[] buf = new byte[1 << 14];
    private int bufSz = 0, bufPtr = 0;

    private int readByte() {
        if (bufSz == -1) throw new RuntimeException("Reading past EOF");
        if (bufPtr >= bufSz) {
            bufPtr = 0;
            try { bufSz = is.read(buf); } catch (IOException e) { throw new RuntimeException(e); }
            if (bufSz <= 0) return -1;
        }
        return buf[bufPtr++];
    }

    private boolean isTrash(int c) { return c < 33 || c > 126; }

    private int skip() {
        int b;
        while ((b = readByte()) != -1 && isTrash(b));
        return b;
    }

    String nextToken() {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while (!isTrash(b)) { sb.appendCodePoint(b); b = readByte(); }
        return sb.toString();
    }

    int nextInt() {
        int ret = 0;
        int b = skip();
        if (b != '-' && (b < '0' || b > '9')) throw new InputMismatchException();
        boolean neg = false;
        if (b == '-') { neg = true; b = readByte(); }
        while (true) {
            if (b >= '0' && b <= '9') ret = ret * 10 + (b - '0');
            else {
                if (b != -1 && !isTrash(b)) throw new InputMismatchException();
                return neg ? -ret : ret;
            }
            b = readByte();
        }
    }

    long nextLong() {
        long ret = 0;
        int b = skip();
        if (b != '-' && (b < '0' || b > '9')) throw new InputMismatchException();
        boolean neg = false;
        if (b == '-') { neg = true; b = readByte(); }
        while (true) {
            if (b >= '0' && b <= '9') ret = ret * 10 + (b - '0');
            else {
                if (b != -1 && !isTrash(b)) throw new InputMismatchException();
                return neg ? -ret : ret;
            }
            b = readByte();
        }
    }
}
